/**
 * Calculate the late fee for an invoice.
 * Late fee is 0.04% of the amount due for every day the invoice is overdue.
 * @param {{ dueDate: string, status: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {number} - Late fee in cents, rounded
 */
export function lateFee(invoice, asOf) {
  if (invoice.status === 'draft') return 0;

  if (invoice.dueDate >= asOf) return 0;

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);

  if (due <= 0) return 0;

  const fee = due * daysOverdue * 0.0004;
  return Math.max(0, roundCents(fee));
}

/**
 * Get a dashboard summary of invoices.
 * @param {Array<{ status: string, customerId: string, dueDate: string, lines: Array, payments?: Array }>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  invoices.forEach(inv => {
    if (counts.hasOwnProperty(inv.status)) {
      counts[inv.status]++;
    }
  });

  const outstanding = invoices
    .filter(inv => inv.status === 'issued' || inv.status === 'partially_paid')
    .reduce((sum, inv) => sum + balanceDue(inv), 0);

  const overdueLst = overdueInvoices(invoices, asOf);
  const overdue = {
    count: overdueLst.length,
    amount: overdueLst.reduce((sum, inv) => sum + inv.due, 0),
  };

  const customerDue = {};
  invoices
    .filter(inv => inv.status === 'issued' || inv.status === 'partially_paid')
    .forEach(inv => {
      const due = balanceDue(inv);
      if (!customerDue[inv.customerId]) {
        customerDue[inv.customerId] = 0;
      }
      customerDue[inv.customerId] += due;
    });

  const topCustomers = Object.entries(customerDue)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue,
    topCustomers,
  };
}

