test('lateFee with complex invoice including discounts and VAT', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
    ],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = lateFee(issued.value, '2026-11-07');
  assert(result >= 0);
});

test('lateFee returns integer cents', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = lateFee(issued.value, '2026-11-10');
  assert.equal(Number.isInteger(result), true);
});

test('lateFee increases with longer delays', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const fee5Days = lateFee(issued.value, '2026-11-11');
  const fee10Days = lateFee(issued.value, '2026-11-16');
  const fee20Days = lateFee(issued.value, '2026-11-26');

  assert(fee5Days < fee10Days);
  assert(fee10Days < fee20Days);
});

